import type { CatalogDiscoveryJobView, CatalogSnapshotListPage, CatalogSnapshotView, ConnectionView } from "/Users/chasen/.codex/worktrees/g4-m1-main-integration-001/ontology-platform/apps/web/src/lib/api/g4-generated.ts";
