    expect(catalogHarness.api.discover).toHaveBeenCalledTimes(1); expect(catalogHarness.replace).toHaveBeenCalledWith("/data/connections?job=job"); view.host.unmount();
  });
  it.each(["history", "job"])("%s先结束不能释放另一读取的互锁", async first => {
